{
 "summary": "Four promise problems are formalized as pairs of yes/no bit-string languages over explicit binary encodings of instances. Each is proved NP-hard in the Karp sense: every NP language, defined via a polynomial-time TM2 verifier with polynomially bounded certificates, poly-time many-one reduces to the promise problem. The problems are Euclidean GapCVP with gap n^{1/400} and integer targets, binary nearest codeword and binary syndrome decoding with gap n^{1/200}, and ℓ_p GapCVP with gap n^{1/(200p)} for every rational p ≥ 1. The definitions track the paper closely. The main caveats: the ℓ_p statement (gap exponent, p ranging only over rationals, rational targets allowed) cannot be checked against the excerpt, and the syndrome-decoding NO set additionally requires the system Hx=b to be consistent, which is a stronger (fine) choice.",
 "glossary": [
  {"decl": "GapCVP.IsNP", "line": 49, "plain": "L ⊆ {0,1}* is in NP iff there are a polynomial bound q and a poly-time (TM2) verifier V such that x ∈ L ⇔ ∃ certificate c with |c| ≤ q(|x|) and V(x,c)=1.", "standard_concept": "NP (verifier definition)", "matches_standard": "yes", "note": ""},
  {"decl": "GapCVP.Comparator.PromiseReduction", "line": 140, "plain": "A poly-time map f on bit strings such that x ∈ L ⇒ f(x) ∈ YES and x ∉ L ⇒ f(x) ∈ NO.", "standard_concept": "Karp reduction to a promise problem", "matches_standard": "yes", "note": ""},
  {"decl": "GapCVP.Comparator.IsNPHardPromise", "line": 147, "plain": "Every NP language Karp-reduces to the promise problem.", "standard_concept": "NP-hardness of a promise problem under deterministic poly-time many-one reductions", "matches_standard": "yes", "note": ""},
  {"decl": "GapCVP.Comparator.gapCVP400Promise", "line": 135, "plain": "YES: encodings of (n>0, nonsingular B∈Z^{n×n}, t∈Z^n, r∈Q>0) with dist_2(t,L(B)) ≤ r. NO: same shape with dist_2(t,L(B)) > n^{1/400} r. The lattice is generated by the columns of B.", "standard_concept": "GapCVP_{n^{1/400}} in ℓ_2", "matches_standard": "yes", "note": "Distances are compared via squares, which is equivalent because both sides are nonnegative."},
  {"decl": "GapCVP.Comparator.binaryNearestCodewordPromise", "line": 187, "plain": "YES: (G∈F2^{n×k}, u, R>0, n>0) with ∃c, wt(u−Gc) ≤ R. NO: ∀c, wt(u−Gc) > n^{1/200} R.", "standard_concept": "Gap nearest codeword over F2", "matches_standard": "yes", "note": "The code is the column span of G rather than the row span; this is only a notational convention."},
  {"decl": "GapCVP.Comparator.binarySyndromeDecodingPromise", "line": 244, "plain": "YES: (H, b, R>0, n>0) with ∃x, Hx=b and wt(x) ≤ R. NO: Hx=b is consistent and every solution has wt(x) > n^{1/200} R.", "standard_concept": "Gap syndrome decoding over F2", "matches_standard": "partly", "note": "The NO set requires consistency of Hx=b, so it is smaller than a definition that treats inconsistent systems as NO. This makes Lean stronger."},
  {"decl": "GapCVP.Comparator.finitePGapCVPPromise", "line": 287, "plain": "For rational p ≥ 1. YES: well-formed (B, t∈Q^n, r) with min_v ‖t−Bv‖_p ≤ r. NO: ‖t−Bv‖_p > n^{1/(200p)} r for all v.", "standard_concept": "GapCVP in ℓ_p", "matches_standard": "unclear", "note": "The paper's exact ℓ_p statement is not in the excerpt. Targets are not required to be integral here, unlike the ℓ_2 version."}
 ],
 "lean_claims": [
  {"theorem": "gapCVP400IsNPHard", "line": 153, "plain": "Every NP language Karp-reduces to the promise problem (YES: dist_2(t,L(B)) ≤ r; NO: dist_2 > n^{1/400} r), with B nonsingular integer, t integer, r>0 rational, n>0."},
  {"theorem": "binaryNearestCodewordIsNPHard", "line": 212, "plain": "Every NP language Karp-reduces to binary nearest codeword with gap n^{1/200}, where n is the block length, R ≥ 1 and n ≥ 1."},
  {"theorem": "binarySyndromeDecodingIsNPHard", "line": 268, "plain": "Every NP language Karp-reduces to binary syndrome decoding with gap n^{1/200}. NO instances must have a consistent syndrome system."},
  {"theorem": "finitePNormGapCVPIsNPHard", "line": 307, "plain": "For every rational p ≥ 1, every NP language Karp-reduces to ℓ_p GapCVP with gap n^{1/(200p)}, using a nonsingular integer basis, rational target and positive rational radius."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1", "plain": "There is a deterministic poly-time map from 3SAT formulas to (B nonsingular in Z^{n×n}, t∈Z^n, r∈Q>0). Satisfiable ⇒ dist_2 ≤ r; unsatisfiable ⇒ dist_2 > n^{1/400} r. Hence GapCVP_{n^{1/400}} is NP-hard."},
  {"ref": "Corollary 15", "plain": "Binary nearest codeword and binary syndrome decoding are NP-hard to approximate within n^{1/200}, with n the block length, under deterministic poly-time many-one reductions."},
  {"ref": "Section 7 finite-norm consequence", "plain": "Not in excerpt (fixed-finite-norm GapCVP hardness mentioned only)."}
 ],
 "coverage": [
  {"paper_ref": "Theorem 1", "lean_theorem": "gapCVP400IsNPHard", "relation": "equivalent", "why": "Same instance shape and gap. NP-hardness is stated for all NP languages rather than via 3SAT, which is equivalent by Cook–Levin."},
  {"paper_ref": "Corollary 15 (nearest codeword)", "lean_theorem": "binaryNearestCodewordIsNPHard", "relation": "equivalent", "why": "Matches. Lean additionally requires R>0 and n>0, which is slightly stronger."},
  {"paper_ref": "Corollary 15 (syndrome decoding)", "lean_theorem": "binarySyndromeDecodingIsNPHard", "relation": "lean_stronger", "why": "The NO set additionally requires a consistent system."},
  {"paper_ref": "Section 7 finite-norm consequence", "lean_theorem": "finitePNormGapCVPIsNPHard", "relation": "different", "why": "The exact paper statement is not in the excerpt. Lean covers only rational p and allows rational targets."}
 ],
 "flags": [
  {"id": "F1", "category": "coverage", "severity": "medium", "decl": "finitePNormGapCVPIsNPHard", "line": 307, "paper_ref": "Section 7", "explanation": "The gap exponent 1/(200p) and the parameter range cannot be checked against the excerpt. Here p ranges only over rationals ≥ 1, whereas the paper likely says any fixed real p ∈ [1,∞).", "polarity": "unclear", "probe_idea": null},
  {"id": "F2", "category": "definition-mismatch", "severity": "low", "decl": "finitePGapCVPPromise", "line": 290, "paper_ref": "Section 7", "explanation": "Unlike gapCVP400, no hasIntegerTarget requirement is imposed, so targets may be rational. This enlarges the YES/NO sets, which is a mildly weaker hardness claim than an integer-target version. Scaling B and t by a common denominator makes the two essentially equivalent.", "polarity": "lean weaker", "probe_idea": null},
  {"id": "F3", "category": "definition-mismatch", "severity": "low", "decl": "binarySyndromeDecodingPromise", "line": 259, "paper_ref": "Corollary 15", "explanation": "The NO set requires Hx=b to be consistent, so the reduction must output consistent systems on unsatisfiable inputs. This is stronger than a definition treating inconsistent systems as NO.", "polarity": "lean stronger", "probe_idea": null},
  {"id": "F4", "category": "other", "severity": "low", "decl": "gapCVP400Promise", "line": 138, "paper_ref": null, "explanation": "The disjointness fields are sorry'd inside the target definitions. They are proof fields and do not affect the statement. Disjointness is in fact true, since n ≥ 1 and r > 0 give n^{1/400} r ≥ r.", "polarity": "n/a", "probe_idea": "Prove disjointness for each promise, using injectivity of encodeInstance and gap factor ≥ 1."}
 ],
