  {"line": 99, "rule": "junk-div", "verdict": "harmless", "why": "(1:ℝ)/400 is real division by a nonzero constant and equals 1/400."},
  {"line": 185, "rule": "junk-div", "verdict": "harmless", "why": "(1:ℝ)/200 is a genuine real exponent."},
  {"line": 195, "rule": "nat-sub", "verdict": "harmless", "why": "This is subtraction of functions into ZMod 2, not ℕ."},
  {"line": 207, "rule": "nat-sub", "verdict": "harmless", "why": "This is subtraction in Fin n → ZMod 2."}
 ]
